/// Fills the editor colors from the scheme; unmapped fields keep `e`'s value.
fn editor(mut e: EditorColors) -> EditorColors {
    e.background = px(0xFFFFFFFF); // TEXT.bg
    e.text = px(0x333333FF); // TEXT.fg
    e.caret = px(0x333333FF); // CARET_COLOR
    e.caret_row = px(0xF8EEC7FF); // CARET_ROW_COLOR
    e.line_number = px(0x333333FF); // LINE_NUMBERS_COLOR
    e.line_number_caret = px(0x333333FF); // LINE_NUMBERS_COLOR
    e.selection = px(0xB0CDE7FF); // SELECTION_BACKGROUND
    e.background_panel = px(0xF7F7F7FF); // DOCUMENTATION_COLOR
    e.search_result = px(0xFFFF00FF); // TEXT_SEARCH_RESULT_ATTRIBUTES.bg
    e.rename_occurrence = px(0xE4E4FFFF); // IDENTIFIER_UNDER_CARET_ATTRIBUTES.bg
    e.matched_brace = px(0x99CCFFFF); // MATCHED_BRACE_ATTRIBUTES.bg
    e.indent_guide = px(0xE0E0E0FF); // INDENT_GUIDE
    e.error_effect = px(0xFF0000FF); // ERRORS_ATTRIBUTES.effect
    e.warning_effect = px(0x333333FF); // WARNING_ATTRIBUTES.effect
    e.weak_warning_effect = px(0xCCCCCCFF); // INFO_ATTRIBUTES.effect
    e.breakpoint_line = px(0xFFC8C8FF); // BREAKPOINT_ATTRIBUTES.bg
    e.execution_line = px(0x2154A6FF); // EXECUTIONPOINT_ATTRIBUTES.bg
    e.inline_value = px(0x868686FF); // DEBUGGER_INLINED_VALUES.fg
    e.error_stripe = px(0xFF0000FF); // ERRORS_ATTRIBUTES.stripe
    e.warning_stripe = px(0xFFFF00FF); // WARNING_ATTRIBUTES.stripe
    e.string = px(0x183691FF); // DEFAULT_STRING.fg
    e.number = px(0x0086B3FF); // DEFAULT_NUMBER.fg
    e.keyword = px(0xA71D5DFF); // DEFAULT_KEYWORD.fg
    e.constant = px(0x0086B3FF); // DEFAULT_CONSTANT.fg
    e.type_name = px(0x20999DFF); // TYPE_PARAMETER_NAME_ATTRIBUTES.fg
    e.annotation = px(0x333333FF); // DEFAULT_METADATA.fg
    e.property = px(0x0086B3FF); // DEFAULT_INSTANCE_FIELD.fg
    e.punctuation = px(0x63A35CFF); // DEFAULT_COMMA.fg
    e.comment = px(0x969896FF); // DEFAULT_LINE_COMMENT.fg
    e.tag = px(0x63A35CFF); // XML_TAG_NAME.fg
    e.attribute = px(0x795DA3FF); // XML_ATTRIBUTE_NAME.fg
    e.variable = px(0x795DA3FF); // DEFAULT_FUNCTION_DECLARATION.fg
    e.invalid = px(0xFF0000FF); // BAD_CHARACTER.fg
    // Kept at the measured value: search_result_current.
    e
}
